/** Reproducible offline bundles. Edit domain source/configuration, never the generated files. */
import { build } from 'esbuild';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const jobs = [
  {
    outfile: 'web/vendor/fsrs.mjs',
    format: 'esm',
    stdin: {
      contents: 'export { fsrs, createEmptyCard, generatorParameters } from "ts-fsrs";',
      resolveDir: process.cwd(),
    },
  },
  {
    outfile: 'web/rating-contract.js',
    format: 'iife',
    globalName: 'WordMemoRatingContract',
    entryPoints: ['web/domain/rating-contract.js'],
  },
  {
    outfile: 'cloud/rating-contract.cjs',
    format: 'cjs',
    platform: 'node',
    entryPoints: ['web/domain/rating-contract.js'],
  },
];
for (const job of jobs) {
  const result = await build({
    ...job,
    bundle: true,
    write: false,
    target: 'es2022',
    legalComments: 'inline',
    banner: { js: '// Generated by tools/vendor-fsrs.mjs. See THIRD_PARTY_NOTICES.md.' },
  });
  const bytes = result.outputFiles[0].contents;
  if (process.argv.includes('--check')) {
    if (!fs.existsSync(job.outfile) || !Buffer.from(bytes).equals(fs.readFileSync(job.outfile)))
      throw Error(`Generated file differs: ${job.outfile}. Run npm run generate.`);
  } else {
    fs.mkdirSync(path.dirname(job.outfile), { recursive: true });
    fs.writeFileSync(job.outfile, bytes);
  }
}
const provenance = {
  package: 'ts-fsrs',
  version: '6.0.0',
  license: 'MIT',
  sha256: crypto.createHash('sha256').update(fs.readFileSync('web/vendor/fsrs.mjs')).digest('hex'),
};
const metadata = JSON.stringify(provenance, null, 2) + '\n';
if (process.argv.includes('--check')) {
  if (fs.readFileSync('web/vendor/fsrs-provenance.json', 'utf8') !== metadata)
    throw Error('FSRS provenance differs');
} else {
  fs.writeFileSync('web/vendor/fsrs-provenance.json', metadata);
  fs.copyFileSync('node_modules/ts-fsrs/LICENSE', 'web/vendor/ts-fsrs-LICENSE.txt');
  fs.copyFileSync(
    'node_modules/@open-spaced-repetition/srs-kit/LICENSE',
    'web/vendor/srs-kit-LICENSE.txt',
  );
}
console.log('Offline algorithm and shared wire contract generated/verified.');
